import re
import string

import pytest
from hypothesis import given
import hypothesis.strategies as st

from roman import to_roman, from_roman


# ---- obviously-correct reference model (written from spec) ----
_REF_TABLE = (
    (1000, "M"),
    (900, "CM"),
    (500, "D"),
    (400, "CD"),
    (100, "C"),
    (90, "XC"),
    (50, "L"),
    (40, "XL"),
    (10, "X"),
    (9, "IX"),
    (5, "V"),
    (4, "IV"),
    (1, "I"),
)

def ref_to_roman(n: int) -> str:
    out = []
    for value, sym in _REF_TABLE:
        q, n = divmod(n, value)
        out.append(sym * q)
    return "".join(out)

_REF_CANONICAL = re.compile(r"M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})")


# ---- concrete examples from spec ----
def test_example_to_roman_4():
    assert to_roman(4) == "IV"

def test_example_to_roman_1994():
    assert to_roman(1994) == "MCMXCIV"

def test_example_to_roman_3999():
    assert to_roman(3999) == "MMMCMXCIX"

def test_example_from_roman_lviii():
    assert from_roman("LVIII") == 58

def test_example_from_roman_iiii_rejects():
    with pytest.raises(ValueError):
        from_roman("IIII")

def test_example_to_roman_zero_rejects():
    with pytest.raises(ValueError):
        to_roman(0)


# ---- reference equivalence ----
@given(st.integers(min_value=1, max_value=3999))
def test_to_roman_matches_reference(n):
    assert to_roman(n) == ref_to_roman(n)

@given(st.integers(min_value=1, max_value=3999))
def test_from_roman_roundtrip_reference(n):
    s = ref_to_roman(n)
    assert from_roman(s) == n

@given(st.integers(min_value=1, max_value=3999))
def test_roundtrip_to_from(n):
    assert from_roman(to_roman(n)) == n


def test_roundtrip_exhaustive_small_sample():
    # deterministic sweep covering units/tens/hundreds/thousands boundaries
    for n in list(range(1, 110)) + [400, 500, 900, 1000, 1994, 3999]:
        assert from_roman(to_roman(n)) == n
        assert to_roman(n) == ref_to_roman(n)

def test_to_from_inverse_on_accepted_strings():
    for n in range(1, 3999 + 1):
        s = ref_to_roman(n)
        assert to_roman(from_roman(s)) == s


# ---- targeted canonical values (hits mis-ordered V/IV table) ----
@pytest.mark.parametrize("n,expected", [
    (1, "I"), (2, "II"), (3, "III"), (4, "IV"), (5, "V"),
    (6, "VI"), (7, "VII"), (8, "VIII"), (9, "IX"), (10, "X"),
    (14, "XIV"), (40, "XL"), (44, "XLIV"), (49, "XLIX"),
    (90, "XC"), (400, "CD"), (900, "CM"), (944, "CMXLIV"),
    (58, "LVIII"), (1994, "MCMXCIV"), (3999, "MMMCMXCIX"),
])
def test_canonical_spot_values(n, expected):
    assert to_roman(n) == expected
    assert from_roman(expected) == n


# ---- range / domain ----
@given(st.integers(min_value=1, max_value=3999))
def test_from_roman_result_in_range(n):
    v = from_roman(ref_to_roman(n))
    assert isinstance(v, int) and not isinstance(v, bool)
    assert 1 <= v <= 3999

@given(st.integers(min_value=1, max_value=3999))
def test_to_roman_uses_only_valid_chars(n):
    s = to_roman(n)
    assert s == s.upper()
    assert set(s) <= set("IVXLCDM")

@pytest.mark.parametrize("n", [0, -1, -100, 4000, 4001, 10000, -3999])
def test_to_roman_out_of_range_raises_value_error(n):
    with pytest.raises(ValueError):
        to_roman(n)

@given(st.integers().filter(lambda x: x < 1 or x > 3999))
def test_to_roman_out_of_range_property(n):
    with pytest.raises(ValueError):
        to_roman(n)


# ---- type strictness ----
@pytest.mark.parametrize("bad", [True, False, 1.0, 4.0, "IV", "4", None, [4], (4,), 4.5])
def test_to_roman_wrong_type_raises_type_error(bad):
    with pytest.raises(TypeError):
        to_roman(bad)

@pytest.mark.parametrize("bad", [None, 0, 1, 58, 4.0, b"X", ["X"], ("X",), True, False])
def test_from_roman_wrong_type_raises_type_error(bad):
    with pytest.raises(TypeError):
        from_roman(bad)


# ---- from_roman strictness ----
@pytest.mark.parametrize("s", [
    "", "iv", "Iv", "IV ", " X", "X\n", "X ", "\tX", "X\t",
    "IIII", "VV", "LL", "DD", "XXXX", "CCCC",
    "IC", "XM", "IL", "IM", "XD", "VX", "LC", "DM", "VL", "VC",
    "IXI", "IVI", "VIV", "IXIX", "MMMM", "MMMMM",
    "IIV", "IIX", "XIXIX", "CMCM", "IXIV",
    "A", "Z", "0", "?", "-", "M M", "MCMXCIV ",
])
def test_from_roman_rejects_noncanonical(s):
    with pytest.raises(ValueError):
        from_roman(s)

@given(st.text(alphabet=string.ascii_letters + string.digits + " \n\t", min_size=0, max_size=8))
def test_from_roman_only_accepts_canonical_strings(s):
    try:
        v = from_roman(s)
    except ValueError:
        return
    # accepted => must be canonical image of v
    assert 1 <= v <= 3999
    assert s == ref_to_roman(v)
    assert _REF_CANONICAL.fullmatch(s) is not None
    assert s != ""

def test_from_roman_rejects_empty_and_mmmm():
    for s in ["", "MMMM", "MMMMMMMMMM"]:
        with pytest.raises(ValueError):
            from_roman(s)

def test_from_roman_rejects_lowercase_and_whitespace():
    for s in ["iv", "ix", "mcmxciv", " X", "X ", "X\n", "\nX", "M C"]:
        with pytest.raises(ValueError):
            from_roman(s)
